    sells = []  # [(price, arrival_time, id, remaining_qty)]
    order_book = {}  # id -> (side, price, remaining_qty, arrival_time)
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_book:
                side, price, remaining_qty, arr_time = order_book[cancel_id]
                del order_book[cancel_id]
                if side == 'buy':
                    buys = [(p, t, oid, q) for p, t, oid, q in buys if oid != cancel_id]
                else:
                    sells = [(p, t, oid, q) for p, t, oid, q in sells if oid != cancel_id]

        elif order[0] == 'limit':
            order_type, order_id, side, price, qty = order
            remaining_qty = qty

